package com.mahesh.library.service;
import com.mahesh.library.config.LibraryProperties; import com.mahesh.library.dto.ApiDtos.*; import com.mahesh.library.dto.PageResponse; import com.mahesh.library.entity.*; import com.mahesh.library.exception.*; import com.mahesh.library.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.time.temporal.ChronoUnit; import java.util.*;
@Service
public class LibraryService {
 private final AuthorRepository authors; private final CategoryRepository categories; private final BookRepository books; private final MemberRepository members; private final MembershipCardRepository cards; private final BorrowRecordRepository borrows; private final LibraryProperties props;
 public LibraryService(AuthorRepository a,CategoryRepository c,BookRepository b,MemberRepository m,MembershipCardRepository mc,BorrowRecordRepository br,LibraryProperties p){authors=a;categories=c;books=b;members=m;cards=mc;borrows=br;props=p;}
 private <T> T require(Optional<T> value,String type,Long id){return value.orElseThrow(()->new NotFoundException(type+" not found: "+id));}
 private Pageable pageable(int page,int size,String sortBy,String direction){if(page<0||size<1||size>100)throw new IllegalArgumentException("page must be >=0 and size must be 1..100"); Sort sort=Sort.by("desc".equalsIgnoreCase(direction)?Sort.Direction.DESC:Sort.Direction.ASC,sortBy==null||sortBy.isBlank()?"id":sortBy);return PageRequest.of(page,size,sort);}
 private AuthorResponse ar(Author a){return new AuthorResponse(a.getId(),a.getName(),a.getBio(),a.getCountry());} private CategoryResponse cr(Category c){return new CategoryResponse(c.getId(),c.getName(),c.getDescription());}
 private BookResponse br(Book b){return new BookResponse(b.getId(),b.getTitle(),b.getIsbn(),b.getPublishedYear(),b.getTotalCopies(),b.getAvailableCopies(),b.getCategory().getId(),b.getCategory().getName(),b.getAuthors().stream().map(Author::getName).sorted().toList());}
 private MemberResponse mr(Member m){MembershipCard c=m.getMembershipCard();return new MemberResponse(m.getId(),m.getFullName(),m.getEmail(),m.getPhone(),m.getMembershipDate(),m.getStatus(),c==null?null:c.getCardNumber(),c==null?null:c.getExpiryDate());}
 private BorrowResponse bor(BorrowRecord r){return new BorrowResponse(r.getId(),r.getBook().getId(),r.getBook().getTitle(),r.getMember().getId(),r.getMember().getFullName(),r.getBorrowDate(),r.getDueDate(),r.getReturnDate(),r.getFineAmount(),r.getStatus());}
 // Authors
 @Transactional public AuthorResponse createAuthor(AuthorRequest x){return ar(authors.save(new Author(x.name(),x.bio(),x.country())));} @Transactional(readOnly=true) public PageResponse<AuthorResponse> listAuthors(int p,int s,String sort,String dir){return PageResponse.from(authors.findAll(pageable(p,s,sort,dir)).map(this::ar));} @Transactional(readOnly=true) public AuthorResponse getAuthor(Long id){return ar(require(authors.findById(id),"Author",id));} @Transactional public AuthorResponse updateAuthor(Long id,AuthorRequest x){Author a=require(authors.findById(id),"Author",id);a.setName(x.name());a.setBio(x.bio());a.setCountry(x.country());return ar(a);} @Transactional public void deleteAuthor(Long id){Author a=require(authors.findById(id),"Author",id);if(authors.countActiveBorrowingsForAuthor(id)>0)throw new ConflictException("Cannot delete author with active borrowings");if(!a.getBooks().isEmpty())throw new ConflictException("Remove author from books before deleting");authors.delete(a);} @Transactional(readOnly=true) public List<BookResponse> authorBooks(Long id){Author a=require(authors.findById(id),"Author",id);return a.getBooks().stream().map(this::br).toList();}
 // Categories
 @Transactional public CategoryResponse createCategory(CategoryRequest x){return cr(categories.save(new Category(x.name(),x.description())));} @Transactional(readOnly=true) public PageResponse<CategoryResponse> listCategories(int p,int s,String sort,String dir){return PageResponse.from(categories.findAll(pageable(p,s,sort,dir)).map(this::cr));} @Transactional(readOnly=true) public CategoryResponse getCategory(Long id){return cr(require(categories.findById(id),"Category",id));} @Transactional public CategoryResponse updateCategory(Long id,CategoryRequest x){Category c=require(categories.findById(id),"Category",id);c.setName(x.name());c.setDescription(x.description());return cr(c);} @Transactional public void deleteCategory(Long id){Category c=require(categories.findById(id),"Category",id);if(books.findAll().stream().anyMatch(b->b.getCategory().getId().equals(id)))throw new ConflictException("Cannot delete a category that has books");categories.delete(c);}
 // Books
 @Transactional public BookResponse createBook(BookRequest x){Category c=require(categories.findById(x.categoryId()),"Category",x.categoryId());if(x.totalCopies()<0)throw new IllegalArgumentException("totalCopies cannot be negative");Book b=new Book(x.title(),x.isbn(),x.publishedYear(),x.totalCopies(),x.totalCopies(),c);if(x.authorIds()!=null)for(Long id:x.authorIds())b.getAuthors().add(require(authors.findById(id),"Author",id));return br(books.save(b));}
 @Transactional(readOnly=true) public PageResponse<BookResponse> listBooks(int p,int s,String sort,String dir){return PageResponse.from(books.findAll(pageable(p,s,sort,dir)).map(this::br));} @Transactional(readOnly=true) public BookResponse getBook(Long id){return br(require(books.findById(id),"Book",id));}
 @Transactional public BookResponse updateBook(Long id,BookRequest x){Book b=require(books.findById(id),"Book",id);int borrowed=b.getBorrowedCopies();if(x.totalCopies()<borrowed)throw new ConflictException("totalCopies cannot be below copies currently borrowed");b.setTitle(x.title());b.setIsbn(x.isbn());b.setPublishedYear(x.publishedYear());b.setTotalCopies(x.totalCopies());b.setAvailableCopies(x.totalCopies()-borrowed);b.setCategory(require(categories.findById(x.categoryId()),"Category",x.categoryId()));b.getAuthors().clear();if(x.authorIds()!=null)for(Long aid:x.authorIds())b.getAuthors().add(require(authors.findById(aid),"Author",aid));return br(b);}
 @Transactional public void deleteBook(Long id){Book b=require(books.findById(id),"Book",id);if(books.countActiveBorrowings(id)>0)throw new ConflictException("Cannot delete a book with active borrowings");books.delete(b);} @Transactional(readOnly=true) public PageResponse<BookResponse> searchBooks(String title,String author,String category,int p,int s,String sort,String dir){Pageable pg=pageable(p,s,sort,dir);String t=title==null?"":title;return PageResponse.from((author!=null&&!author.isBlank()?books.searchByAuthor(t,author,pg):books.search(t,category,pg)).map(this::br));} @Transactional(readOnly=true) public List<BookResponse> availableBooks(){return books.findAvailableBooks().stream().map(this::br).toList();}
 // Members
 @Transactional public MemberResponse createMember(MemberRequest x){return mr(members.save(new Member(x.fullName(),x.email(),x.phone())));} @Transactional(readOnly=true) public PageResponse<MemberResponse> listMembers(int p,int s,String sort,String dir){return PageResponse.from(members.findAll(pageable(p,s,sort,dir)).map(this::mr));} @Transactional(readOnly=true) public MemberResponse getMember(Long id){return mr(require(members.findById(id),"Member",id));} @Transactional public MemberResponse updateMember(Long id,MemberRequest x){Member m=require(members.findById(id),"Member",id);m.setFullName(x.fullName());m.setEmail(x.email());m.setPhone(x.phone());return mr(m);} @Transactional public void deleteMember(Long id){Member m=require(members.findById(id),"Member",id);if(members.countActiveBorrowings(id)>0)throw new ConflictException("Cannot delete a member with active borrowings");members.delete(m);} @Transactional public MemberResponse setMemberStatus(Long id,MemberStatus status){Member m=require(members.findById(id),"Member",id);m.setStatus(status);return mr(m);}
 @Transactional public MemberResponse issueCard(Long memberId,CardRequest x){Member m=require(members.findById(memberId),"Member",memberId);if(x.expiryDate().isBefore(x.issueDate()))throw new IllegalArgumentException("Card expiry must not precede issue date");MembershipCard card=new MembershipCard(x.cardNumber(),x.issueDate(),x.expiryDate(),m);m.setMembershipCard(card);return mr(m);}
 @Transactional(readOnly=true) public List<BorrowResponse> memberHistory(Long id){require(members.findById(id),"Member",id);return borrows.findHistoryByMember(id).stream().map(this::bor).toList();}
 // Borrow/return: one transaction keeps inventory and record changes consistent.
 @Transactional public BorrowResponse borrow(Long bookId,Long memberId){Book b=require(books.findById(bookId),"Book",bookId);Member m=require(members.findById(memberId),"Member",memberId);LocalDate today=LocalDate.now();if(m.getStatus()!=MemberStatus.ACTIVE)throw new ConflictException("Inactive members cannot borrow");MembershipCard card=m.getMembershipCard();if(card==null||!card.isValidOn(today))throw new ConflictException("A valid membership card is required");if(b.getAvailableCopies()<1)throw new ConflictException("No copies available");if(members.countActiveBorrowings(memberId)>=3)throw new ConflictException("Member has reached the limit of 3 active borrowings");if(!borrows.findActiveDuplicate(memberId,bookId).isEmpty())throw new ConflictException("Member already has this book borrowed");b.setAvailableCopies(b.getAvailableCopies()-1);return bor(borrows.save(new BorrowRecord(b,m,today,today.plusDays(props.loanPeriodDays()))));}
 @Transactional public BorrowResponse returnBook(Long borrowId){BorrowRecord r=require(borrows.findById(borrowId),"Borrow record",borrowId);if(r.getStatus()==BorrowStatus.RETURNED)throw new ConflictException("Borrow record has already been returned");LocalDate today=LocalDate.now();long lateDays=Math.max(0,ChronoUnit.DAYS.between(r.getDueDate(),today));BigDecimal fine=props.finePerDay().multiply(BigDecimal.valueOf(lateDays));r.markReturned(today,fine);r.getBook().setAvailableCopies(r.getBook().getAvailableCopies()+1);return bor(r);}
 @Transactional(readOnly=true) public PageResponse<BorrowResponse> listBorrows(int p,int s,String sort,String dir){return PageResponse.from(borrows.findAll(pageable(p,s,sort,dir)).map(this::bor));} @Transactional(readOnly=true) public List<BorrowResponse> overdue(){return borrows.findOverdueWithDetails(LocalDate.now()).stream().map(this::bor).toList();} @Transactional(readOnly=true) public List<BorrowResponse> activeByMember(Long id){require(members.findById(id),"Member",id);return borrows.findActiveByMember(id).stream().map(this::bor).toList();} @Transactional public int refreshOverdue(){return borrows.markOverdue(LocalDate.now());} @Transactional(readOnly=true) public BigDecimal memberFines(Long id){require(members.findById(id),"Member",id);return members.totalFineForMember(id);} @Transactional(readOnly=true) public List<TopBook> topBooks(){return books.findTopBorrowedBooks(PageRequest.of(0,5)).stream().map(x->new TopBook((String)x[0],((Number)x[1]).longValue())).toList();}
}